#include <set>
#include <vector>
#include <algorithm>

int main() {
    std::set<int> s;
    auto it = s.begin(); // Initial hint

    std::vector<int> sorted_data = {10, 20, 30};

    // Sequential insertion using the previous result as a hint
    for (int val : sorted_data) {
        // O(1) amortized if val > *it (and it is end() or points to prev element)
        it = s.insert(it, val); 
    }
    // Total complexity: O(N) rather than O(N log N)
    return 0;
}
